export const UI_I18N_RUNTIME = String.raw`(function(messages){
  "use strict";
  const languages=["en","ru","es","de","zh"], saved=new WeakMap();
  let language;
  try { language=localStorage.getItem("crot.language"); } catch { /* Private/opaque origins may disallow storage. */ }
  if(!languages.includes(language)) language=(navigator.language||"en").toLowerCase().split("-")[0];
  if(!languages.includes(language)) language="en";
  const t=(text)=>messages[text]?.[languages.indexOf(language)] || text;
  function translate(text){
    if(Object.hasOwn(messages,text)) return t(text);
    const quota=/^Remote devices: (\d+) \/ (\d+)$/.exec(text);
    if(quota) return t("Remote devices: {used} / {max}").replace("{used}",quota[1]).replace("{max}",quota[2]);
    const requests=/^(\d+) (request|requests) waiting for your approval$/.exec(text);
    if(requests) return t(requests[2]==="request"?"{count} request waiting for your approval":"{count} requests waiting for your approval").replace("{count}",requests[1]);
    return text;
  }
  function setText(node,source){
    const translated=translate(source);
    saved.set(node.firstChild || node,{source,translated});
    if(node.textContent!==translated) node.textContent=translated;
    if(node.firstChild) saved.set(node.firstChild,{source,translated});
  }
  function apply(root=document.body){
    if(!root) return;
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
    const pending=[]; let node;
    while((node=walker.nextNode())) pending.push(node);
    for(const n of pending){
      if(n.parentElement?.closest("script,style,code,pre,dd,option,[data-no-i18n]")) continue;
      const old=saved.get(n); let raw=n.textContent;
      if(old && raw===old.translated) raw=old.source;
      const key=raw.trim().replace(/\s+/g," ");
      const prefix=/^[●○] /.exec(key)?.[0] || "";
      const lookup=prefix ? key.slice(prefix.length) : key;
      const translated=translate(lookup);
      if(translated===lookup && !Object.hasOwn(messages,lookup) && !saved.has(n)) continue;
      const value=raw.replace(raw.trim(),prefix+translated); saved.set(n,{source:raw,translated:value});
      if(n.textContent!==value) n.textContent=value;
    }
    for(const n of document.querySelectorAll("[placeholder]")){
      const source=n.dataset.i18nPlaceholder || n.getAttribute("placeholder");
      n.dataset.i18nPlaceholder=source;n.setAttribute("placeholder",translate(source));
    }
    document.documentElement.lang=language;
    document.querySelectorAll("[data-language]").forEach(s=>{s.value=language;});
  }
  function setLanguage(value){
    if(!languages.includes(value)) return;
    language=value; try{localStorage.setItem("crot.language",language);}catch{ /* Storage optional. */ }
    apply(); document.dispatchEvent(new CustomEvent("crot:language",{detail:language}));
  }
  function start(){
    const header=document.querySelector("header");
    if(header&&!header.querySelector("[data-language]")){
      const selector=document.createElement("select");selector.className="language";selector.dataset.language="";
      selector.setAttribute("aria-label","Language / Язык / Idioma / Sprache / 语言");
      for(const l of languages){const option=document.createElement("option");option.value=l;option.textContent=l.toUpperCase();selector.append(option);}
      selector.addEventListener("change",()=>setLanguage(selector.value));
      (header.querySelector(".actions")||header).append(selector);
    }
    apply();
    const observer=new MutationObserver(records=>{
      observer.disconnect();
      const roots=new Set(records.map(r=>r.target.nodeType===Node.TEXT_NODE?r.target.parentElement:r.target));
      for(const root of roots) if(root instanceof Element) apply(root);
      observer.observe(document.body,{childList:true,subtree:true,characterData:true});
    });
    observer.observe(document.body,{childList:true,subtree:true,characterData:true});
  }
  window.CrotI18n={t:translate,setText,apply,setLanguage,get language(){return language;}};
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",start,{once:true}); else start();
})`;
export const I18N_SCRIPT = UI_I18N_RUNTIME + "(" + UI_MESSAGES_JSON + ");";
